    public static BannerPattern registerNewPattern(String textureId, String hashId, String desc, boolean isItem) {
        String filename = "wfm_" + textureId;
        String hashname = "wfm_" + hashId;
        if (DatagenModLoader.isRunningDataGen()) {
            hashToName.put(hashname, desc);
        }
        BannerPattern pattern = BannerPattern.create(hashname.toUpperCase(), filename, hashname, isItem);
        patterns.add(pattern);
        patternToFaction.put(hashId, pattern);
        LOTRLog.info("Registered banner pattern '%s' (hashname='%s', filename='%s', ordinal=%d, hasPatternItem=%b)",
                hashname, pattern.getHashname(), pattern.getFilename(), pattern.ordinal(), isItem);
        return pattern;
