import wfm.common.item.LOTRSwordItem;
import wfm.common.item.enchantment.WFMEnchantmentHelper;
import wfm.common.item.enchantment.WFMEnchantmentTier;
import wfm.common.item.enchantment.WFMEnchantments;
import wfm.common.item.enchantment.types.DenseMaterialsEnch;
import wfm.common.item.enchantment.types.tools.CarbonStoneAlloyEnch;

import java.util.Collection;
import java.util.UUID;
import java.util.function.Consumer;

@Mixin(ItemStack.class)
public class ItemStackMixin {

    @ModifyVariable(
            method = "hurtAndBreak(ILnet/minecraft/entity/LivingEntity;Ljava/util/function/Consumer;)V",
            at = @At("HEAD"),
            ordinal = 0,
            argsOnly = true
    )
    private int wfm$adjustFactionWeaponDurabilityDamage(int amount, int originalAmount, LivingEntity entity, Consumer<LivingEntity> onBroken) {
        if (!(entity instanceof PlayerEntity)) {
            return amount;
        }
        ItemStack stack = (ItemStack) (Object) this;
        return TechTreeEffectHandler.adjustWeaponDurabilityDamage((PlayerEntity) entity, stack, amount);
    }

    @Inject(method = "getMaxDamage", at = @At("HEAD"), cancellable = true)
    public void getMaxDamage(CallbackInfoReturnable<Integer> cir) {
        ItemStack stack = (ItemStack) (Object) this;
        
        // Проверяем, является ли предмет инструментом и имеет ли тир зачарование
        if (stack.getItem() instanceof ToolItem) {
            WFMEnchantmentTier tier = WFMEnchantmentHelper.getItemTier(stack);
            if (tier != null && tier.getDurabilityBonus() > 0) {
                // Получаем оригинальную прочность предмета
                int originalDurability = stack.getItem().getMaxDamage(stack);
                
                // Добавляем бонус прочности от тира
                int bonusDurability = (int) tier.getDurabilityBonus();
                int totalDurability = originalDurability + bonusDurability;
                if (WFMEnchantmentHelper.hasEnchantment(WFMEnchantments.carbon_stone_alloy, stack)) {
                    totalDurability *= CarbonStoneAlloyEnch.BONUS;
                }
                
                cir.setReturnValue(totalDurability);
            }
        }
        
        // Проверяем, является ли предмет броней и имеет ли зачарование DenseMaterialsEnch
        if (stack.getItem() instanceof ArmorItem) {
            if (WFMEnchantmentHelper.hasEnchantment(WFMEnchantments.dense_materials, stack)) {
                // Получаем оригинальную прочность предмета
                int originalDurability = stack.getItem().getMaxDamage(stack);
                
                // Умножаем прочность на TOUGHNESS
                int totalDurability = (int) (originalDurability * DenseMaterialsEnch.TOUGHNESS);
                
                cir.setReturnValue(totalDurability);
            }
        }
    }

    @Inject(method = "getAttributeModifiers", at = @At("RETURN"), cancellable = true)
    public void getAttributeModifiers(EquipmentSlotType slot, CallbackInfoReturnable<Multimap<Attribute, AttributeModifier>> cir) {
        ItemStack stack = (ItemStack) (Object) this;
        Multimap<Attribute, AttributeModifier> originalModifiers = cir.getReturnValue();
        
        if (originalModifiers == null || originalModifiers.isEmpty()) {
            return;
        }
        
        // Проверяем, является ли предмет мечом (ванильным)
        if (stack.getItem() instanceof SwordItem && !(stack.getItem() instanceof LOTRSwordItem)) {
            // Снижаем урон всех ванильных мечей до 2.5
            Multimap<Attribute, AttributeModifier> modifiedModifiers = LinkedHashMultimap.create(originalModifiers);
            Collection<AttributeModifier> attackDamageModifiers = modifiedModifiers.removeAll(Attributes.ATTACK_DAMAGE);
            
            if (!attackDamageModifiers.isEmpty()) {
                // Создаем новый модификатор с уроном 2.5
                // Используем UUID из первого существующего модификатора или создаем новый
                UUID modifierUUID = attackDamageModifiers.iterator().next().getId();
                AttributeModifier newModifier = new AttributeModifier(
                    modifierUUID,
                    "Weapon modifier",
                    2.5D,
                    AttributeModifier.Operation.ADDITION
                );
                modifiedModifiers.put(Attributes.ATTACK_DAMAGE, newModifier);
                cir.setReturnValue(modifiedModifiers);
            }
        }
        // Проверяем, является ли предмет инструментом (включая топоры)
        else if (stack.getItem() instanceof ToolItem) {
            // Снижаем урон всех инструментов до 0.5
            Multimap<Attribute, AttributeModifier> modifiedModifiers = LinkedHashMultimap.create(originalModifiers);
            Collection<AttributeModifier> attackDamageModifiers = modifiedModifiers.removeAll(Attributes.ATTACK_DAMAGE);
            
            if (!attackDamageModifiers.isEmpty()) {
                // Создаем новый модификатор с уроном 0.5
                UUID modifierUUID = attackDamageModifiers.iterator().next().getId();
                AttributeModifier newModifier = new AttributeModifier(
                    modifierUUID,
                    "Weapon modifier",
                    0.5D,
                    AttributeModifier.Operation.ADDITION
                );
                modifiedModifiers.put(Attributes.ATTACK_DAMAGE, newModifier);
                cir.setReturnValue(modifiedModifiers);
            }
        }
    }
}

