/**
 * Дополнительная защита для 2x2 крафта в инвентаре игрока.
 * Применяет ту же логику блокировки, что и обычный верстак.
 */
@Mixin(PlayerContainer.class)
public class PlayerContainerMixin {

    @Shadow
    @Final
    private CraftingInventory craftSlots;

    @Shadow
    @Final
    private CraftResultInventory resultSlots;

    @Shadow
    @Final
    private PlayerEntity owner;

    @Inject(method = "slotsChanged", at = @At("TAIL"))
    private void wfm$enforceRecipeLocksInInventoryCraft(IInventory inventory, CallbackInfo ci) {
        if (owner.level.isClientSide) {
            return;
        }

        Optional<ICraftingRecipe> optRecipe = owner.level.getServer().getRecipeManager()
                .getRecipeFor(IRecipeType.CRAFTING, craftSlots, owner.level);

        if (!optRecipe.isPresent()) {
            return;
        }

        ICraftingRecipe recipe = optRecipe.get();
        ResourceLocation requiredUpgrade = null;
        if (recipe instanceof FactionShapedRecipe) {
            requiredUpgrade = ((FactionShapedRecipe) recipe).getRequiredUpgrade();
        } else if (recipe instanceof FactionShapelessRecipe) {
            requiredUpgrade = ((FactionShapelessRecipe) recipe).getRequiredUpgrade();
        }

        boolean upgradeOk = requiredUpgrade == null || isUpgradeUnlocked(owner, requiredUpgrade);
        boolean recipeOk = isRecipeUnlockedByTechTree(owner, recipe.getId());

        if (upgradeOk && recipeOk) {
            return;
        }

        resultSlots.setItem(0, ItemStack.EMPTY);
        if (owner instanceof ServerPlayerEntity) {
            ((ServerPlayerEntity) owner).connection.send(
                    new SSetSlotPacket(owner.containerMenu.containerId, 0, ItemStack.EMPTY)
            );
        }
    }

    private static boolean isUpgradeUnlocked(PlayerEntity player, ResourceLocation upgradeId) {
        Faction playerFaction = LOTRLevelData.serverInstance()
                .getData(player)
                .getAlignmentData()
                .getPledgeFaction();
        if (playerFaction == null) {
            return false;
        }

        TechTree tree = TechTreeManager.serverInstance().getTechTree(playerFaction);
        if (tree == null) {
            return false;
        }

        TechTreeNode node = tree.getNodeByUpgrade(upgradeId);
        if (node == null) {
            return false;
        }

        FactionTechData techData = LOTRLevelData.serverInstance()
                .getData(player.getCommandSenderWorld(), player.getUUID())
                .getTechDataModule().getData(playerFaction.getName());
        return techData.isNodeUnlocked(node.getId());
    }

    private static boolean isRecipeUnlockedByTechTree(PlayerEntity player, ResourceLocation recipeId) {
        Faction playerFaction = LOTRLevelData.serverInstance()
                .getData(player)
                .getAlignmentData()
                .getPledgeFaction();
        if (playerFaction == null) {
            return false;
        }

        TechTree tree = TechTreeManager.serverInstance().getTechTree(playerFaction);
        if (tree == null) {
            return false;
        }

        FactionTechData techData = LOTRLevelData.serverInstance()
                .getData(player.getCommandSenderWorld(), player.getUUID())
                .getTechDataModule().getData(playerFaction.getName());
        TechUpgradeManager upgradeManager = TechUpgradeManager.serverInstance();
        return techData.isRecipeUnlocked(recipeId, tree, upgradeManager);
    }
}

