import wfm.common.recipe.FactionShapelessRecipe;

import java.util.Optional;

/**
 * Миксин для ванильного верстака (WorkbenchContainer).
 * Добавляет проверку разблокировки рецептов через дерево технологий.
 * Если рецепт требует определенный upgrade и он не разблокирован в фракции игрока,
 * результат крафта будет пустым.
 * 
 * Примечание: Этот миксин проверяет только FactionShapedRecipe/FactionShapelessRecipe,
 * которые случайно оказались доступны на ванильном верстаке. Ванильные рецепты
 * не имеют required_upgrade и всегда доступны.
 */
@Mixin(WorkbenchContainer.class)
public class WorkbenchContainerMixin {

    /**
     * Инжектируется в начало метода slotChangedCraftingGrid для проверки
     * требований дерева технологий перед показом результата крафта.
     */
    @Inject(
        method = "slotChangedCraftingGrid",
        at = @At("HEAD"),
        cancellable = true
    )
    private static void wfm$checkUpgradeRequirement(
            int windowId,
            World world,
            PlayerEntity player,
            CraftingInventory craftingInventory,
            CraftResultInventory resultInventory,
            CallbackInfo ci
    ) {
        if (world.isClientSide) {
            return;
        }
        
        // Находим подходящий рецепт
        Optional<ICraftingRecipe> optRecipe = world.getServer().getRecipeManager()
                .getRecipeFor(IRecipeType.CRAFTING, craftingInventory, world);
        
        if (optRecipe.isPresent()) {
            ICraftingRecipe recipe = optRecipe.get();
            
            // Получаем требуемое улучшение
            ResourceLocation requiredUpgrade = null;
            if (recipe instanceof FactionShapedRecipe) {
                requiredUpgrade = ((FactionShapedRecipe) recipe).getRequiredUpgrade();
            } else if (recipe instanceof FactionShapelessRecipe) {
                requiredUpgrade = ((FactionShapelessRecipe) recipe).getRequiredUpgrade();
            }
            
            // Если у рецепта явно задан required_upgrade, он тоже обязан быть открыт
            if (requiredUpgrade != null && !isUpgradeUnlocked(player, requiredUpgrade)) {
                // Рецепт заблокирован
                resultInventory.setItem(0, ItemStack.EMPTY);
                
                if (player instanceof ServerPlayerEntity) {
                    ((ServerPlayerEntity) player).connection.send(
                            new SSetSlotPacket(windowId, 0, ItemStack.EMPTY)
                    );
                }
                
                ci.cancel();
                return;
            }

            // Проверяем разблокировку по RECIPE_UNLOCK узлам tech tree
            if (!isRecipeUnlockedByTechTree(player, recipe.getId())) {
                resultInventory.setItem(0, ItemStack.EMPTY);

                if (player instanceof ServerPlayerEntity) {
                    ((ServerPlayerEntity) player).connection.send(
                            new SSetSlotPacket(windowId, 0, ItemStack.EMPTY)
                    );
                }

                ci.cancel();
            }
        }
    }
    
    private static boolean isUpgradeUnlocked(PlayerEntity player, ResourceLocation upgradeId) {
        // Получаем фракцию игрока
        Faction playerFaction = LOTRLevelData.serverInstance()
                .getData(player)
                .getAlignmentData()
                .getPledgeFaction();
        
        if (playerFaction == null) {
            return false;
        }
        
        // Получаем дерево технологий
        TechTree tree = TechTreeManager.serverInstance().getTechTree(playerFaction);
        if (tree == null) {
            return false;
        }
        
        // Проверяем наличие upgrade в дереве
        TechTreeNode node = tree.getNodeByUpgrade(upgradeId);
        if (node == null) {
            return false;
        }
        
        // Проверяем разблокировку у этого игрока
        FactionTechData techData = LOTRLevelData.serverInstance()
                .getData(player.getCommandSenderWorld(), player.getUUID())
                .getTechDataModule().getData(playerFaction.getName());
        return techData.isNodeUnlocked(node.getId());
    }

    private static boolean isRecipeUnlockedByTechTree(PlayerEntity player, ResourceLocation recipeId) {
        Faction playerFaction = LOTRLevelData.serverInstance()
                .getData(player)
                .getAlignmentData()
                .getPledgeFaction();
        if (playerFaction == null) {
            return false;
        }

        TechTree tree = TechTreeManager.serverInstance().getTechTree(playerFaction);
        if (tree == null) {
            return false;
        }

        FactionTechData techData = LOTRLevelData.serverInstance()
                .getData(player.getCommandSenderWorld(), player.getUUID())
                .getTechDataModule().getData(playerFaction.getName());
        TechUpgradeManager upgradeManager = TechUpgradeManager.serverInstance();
        return techData.isRecipeUnlocked(recipeId, tree, upgradeManager);
    }
}

