import net.minecraft.tileentity.SmokerTileEntity;
import net.minecraft.util.ResourceLocation;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
import wfm.common.data.LOTRLevelData;
import wfm.common.fac.Faction;
import wfm.common.fac.techtree.FactionTechData;
import wfm.common.fac.techtree.TechTree;
import wfm.common.fac.techtree.TechTreeManager;
import wfm.common.fac.techtree.TechUpgradeManager;

import java.util.Optional;

@Mixin(Slot.class)
public class FurnaceResultSlotMixin {

    @Inject(method = "mayPickup", at = @At("HEAD"), cancellable = true)
    private void wfm$checkFurnaceRecipeTechLock(PlayerEntity player, CallbackInfoReturnable<Boolean> cir) {
        if (player.level.isClientSide) {
            return;
        }

        Slot slot = (Slot) (Object) this;
        if (!(slot instanceof FurnaceResultSlot)) {
            return;
        }

        ResourceLocation recipeId = getCurrentRecipeId(player, slot);
        if (recipeId == null) {
            return;
        }

        if (!isRecipeUnlockedByTechTree(player, recipeId)) {
            cir.setReturnValue(false);
        }
    }

    private static ResourceLocation getCurrentRecipeId(PlayerEntity player, Slot slot) {
        IInventory inv = slot.container;
        if (!(inv instanceof AbstractFurnaceTileEntity)) {
            return null;
        }
        AbstractFurnaceTileEntity furnace = (AbstractFurnaceTileEntity) inv;
        if (furnace.getItem(0).isEmpty()) {
            return null;
        }

        IRecipeType<? extends AbstractCookingRecipe> recipeType = getRecipeType(furnace);
        if (recipeType == null) {
            return null;
        }

        Inventory probe = new Inventory(furnace.getItem(0).copy());
        Optional<? extends AbstractCookingRecipe> recipe = player.level.getRecipeManager()
                .getRecipeFor(recipeType, probe, player.level);
        return recipe.map(AbstractCookingRecipe::getId).orElse(null);
    }

    private static IRecipeType<? extends AbstractCookingRecipe> getRecipeType(AbstractFurnaceTileEntity furnace) {
        if (furnace instanceof SmokerTileEntity) {
            return IRecipeType.SMOKING;
        }
        if (furnace instanceof BlastFurnaceTileEntity) {
            return IRecipeType.BLASTING;
        }
        if (furnace instanceof FurnaceTileEntity) {
            return IRecipeType.SMELTING;
        }
        return null;
    }

    private static boolean isRecipeUnlockedByTechTree(PlayerEntity player, ResourceLocation recipeId) {
        Faction playerFaction = LOTRLevelData.serverInstance()
                .getData(player)
                .getAlignmentData()
                .getPledgeFaction();
        if (playerFaction == null) {
            return false;
        }

        TechTree tree = TechTreeManager.serverInstance().getTechTree(playerFaction);
        if (tree == null) {
            return false;
        }

        FactionTechData techData = LOTRLevelData.serverInstance()
                .getData(player.getCommandSenderWorld(), player.getUUID())
                .getTechDataModule().getData(playerFaction.getName());
        TechUpgradeManager upgradeManager = TechUpgradeManager.serverInstance();
        return techData.isRecipeUnlocked(recipeId, tree, upgradeManager);
    }
}

